// ============================================================================
// HỆ THỐNG QUẢN LÝ DỮ LIỆU DƯỢC THƯ NỘI VIỆN & TÙY BIẾN (ADMIN CRUD HELPER)
// ============================================================================
export const CUSTOM_DRUGS_STORAGE_KEY = "clinicalrx_custom_drugs_store_v4";

export function sortDrugsAlphabetical(drugList) {
  if (!Array.isArray(drugList)) return [];
  return drugList.sort((a, b) => {
    const nameA = (a.name || a.inn || "").trim();
    const nameB = (b.name || b.inn || "").trim();
    return nameA.localeCompare(nameB, "vi", { sensitivity: "base" });
  });
}

export function getActiveDrugsDatabase() {
  try {
    const raw = localStorage.getItem(CUSTOM_DRUGS_STORAGE_KEY);
    let list = [...DRUGS_DATABASE];

    if (raw) {
      try {
        if (/[\x00-\x08\x0B\x0C\x0E-\x1F]/.test(raw) || raw.includes("\\u0010") || raw.includes("\\u0001")) {
          console.warn("Dọn sạch bộ nhớ cache bị lỗi font ký tự lạ.");
          localStorage.removeItem(CUSTOM_DRUGS_STORAGE_KEY);
        } else {
          const store = JSON.parse(raw);
          // 1. Lọc bỏ các thuốc bị Quản trị viên xóa
        if (Array.isArray(store.deletedIds) && store.deletedIds.length > 0) {
          list = list.filter(d => !store.deletedIds.includes(d.id));
        }
        // 2. Cập nhật các thuốc đã được chỉnh sửa
        if (store.modified && typeof store.modified === "object") {
          list = list.map(d => store.modified[d.id] ? { ...d, ...store.modified[d.id] } : d);
        }
        // 3. Bổ sung các thuốc mới thêm
        if (Array.isArray(store.addedDrugs) && store.addedDrugs.length > 0) {
          // Lọc trùng ID nếu đã có trong DRUGS_DATABASE
          const addedFiltered = store.addedDrugs.filter(ad => !list.some(d => d.id === ad.id));
          list = [...addedFiltered, ...list];
        }
        }
      } catch (parseErr) {
        console.warn("Lỗi khi giải mã localStorage custom drugs:", parseErr);
      }
    }

    // 4. Bổ sung các file PDF lưu trữ vĩnh viễn trên kho GitHub (assets/pdfs) CHO MỌI THIẾT BỊ
    list.forEach(drug => {
      const staticPdfs = STATIC_PDF_CATALOG.filter(p => p.drugId === drug.id);
      if (staticPdfs.length > 0) {
        if (!drug.attachments || !Array.isArray(drug.attachments) || drug.attachments.length === 0) {
          drug.attachments = JSON.parse(JSON.stringify(staticPdfs));
        } else {
          const existingNames = new Set(drug.attachments.map(a => (a.fileName || a.title || "").toLowerCase()));
          staticPdfs.forEach(sp => {
            if (!existingNames.has((sp.fileName || "").toLowerCase()) && !existingNames.has((sp.title || "").toLowerCase())) {
              drug.attachments.push(JSON.parse(JSON.stringify(sp)));
            }
          });
        }
      }
    });

    // 5. Tự động sắp xếp lại toàn bộ danh mục theo thứ tự ABC (A - Z)
    return sortDrugsAlphabetical(list);
  } catch (err) {
    console.error("Lỗi khi đọc danh mục thuốc tùy biến:", err);
    return sortDrugsAlphabetical([...DRUGS_DATABASE]);
  }
}

export function saveOrUpdateDrug(drugData) {
  try {
    const raw = localStorage.getItem(CUSTOM_DRUGS_STORAGE_KEY);
    const store = raw ? JSON.parse(raw) : { deletedIds: [], modified: {}, addedDrugs: [] };

    // Kiểm tra xem thuốc này có trong cơ sở dữ liệu gốc không
    const existsInCore = DRUGS_DATABASE.some(d => d.id === drugData.id);

    if (existsInCore) {
      store.modified[drugData.id] = drugData;
      // Nếu trước đó từng bị xóa, khôi phục lại
      store.deletedIds = (store.deletedIds || []).filter(id => id !== drugData.id);
    } else {
      // Kiểm tra xem đã có trong addedDrugs chưa
      const existingAddedIdx = (store.addedDrugs || []).findIndex(d => d.id === drugData.id);
      if (existingAddedIdx >= 0) {
        store.addedDrugs[existingAddedIdx] = drugData;
      } else {
        if (!store.addedDrugs) store.addedDrugs = [];
        store.addedDrugs.push(drugData);
      }
      // Tự động sắp xếp danh sách addedDrugs theo ABC
      sortDrugsAlphabetical(store.addedDrugs);
    }

    localStorage.setItem(CUSTOM_DRUGS_STORAGE_KEY, JSON.stringify(store));

    // Đồng bộ tự động lên Supabase Cloud Database nếu có kết nối
    if (window.supabase) {
      try {
        const { getSupabaseCredentials } = window.__clinicalrx_config || {};
        if (getSupabaseCredentials) {
          const { url, key } = getSupabaseCredentials();
          if (url && key) {
            const client = window.supabase.createClient(url, key);
            client.from("custom_drugs").upsert({
              id: drugData.id,
              data: drugData,
              updated_at: new Date().toISOString()
            }).then(({ error }) => {
              if (error) console.warn("Supabase sync warning:", error);
              else console.log("Đã đồng bộ thuốc lên Supabase Cloud:", drugData.name);
            });
          }
        }
      } catch (e) {
        console.warn("Lỗi gửi Supabase:", e);
      }
    }
    return { success: true, drug: drugData };
  } catch (err) {
    console.error("Lỗi khi lưu thuốc:", err);
    return { success: false, error: err.message };
  }
}

export function deleteDrugById(drugId) {
  try {
    const raw = localStorage.getItem(CUSTOM_DRUGS_STORAGE_KEY);
    const store = raw ? JSON.parse(raw) : { deletedIds: [], modified: {}, addedDrugs: [] };

    // Xóa khỏi danh sách addedDrugs nếu là thuốc tự thêm
    if (Array.isArray(store.addedDrugs)) {
      store.addedDrugs = store.addedDrugs.filter(d => d.id !== drugId);
    }
    // Đánh dấu vào danh sách đã xóa nếu là thuốc gốc
    if (!store.deletedIds) store.deletedIds = [];
    if (!store.deletedIds.includes(drugId)) {
      store.deletedIds.push(drugId);
    }
    // Xóa khỏi modified nếu có
    if (store.modified && store.modified[drugId]) {
      delete store.modified[drugId];
    }

    localStorage.setItem(CUSTOM_DRUGS_STORAGE_KEY, JSON.stringify(store));

    // Đồng bộ xóa trên Supabase Cloud
    if (window.supabase) {
      try {
        const { getSupabaseCredentials } = window.__clinicalrx_config || {};
        if (getSupabaseCredentials) {
          const { url, key } = getSupabaseCredentials();
          if (url && key) {
            const client = window.supabase.createClient(url, key);
            client.from("custom_drugs").delete().eq("id", drugId).then(() => {
              console.log("Đã xóa thuốc trên Supabase Cloud:", drugId);
            });
          }
        }
      } catch (err) {}
    }

    return { success: true };
  } catch (err) {
    console.error("Lỗi khi xóa thuốc:", err);
    return { success: false, error: err.message };
  }
}

export function resetCustomDrugsDatabase() {
  try {
    localStorage.removeItem(CUSTOM_DRUGS_STORAGE_KEY);
    return { success: true };
  } catch (err) {
    return { success: false, error: err.message };
  }
}

// ============================================================================
// ĐỒNG BỘ CƠ SỞ DỮ LIỆU ĐÁM MÂY SUPABASE (CLOUD SYNC)
// ============================================================================
export async function syncCustomDrugsFromSupabase() {
  if (!window.supabase) return false;
  try {
    const { getSupabaseCredentials } = window.__clinicalrx_config || {};
    if (!getSupabaseCredentials) return false;
    const { url, key } = getSupabaseCredentials();
    if (!url || !key) return false;

    const client = window.supabase.createClient(url, key);
    const { data, error } = await client.from("custom_drugs").select("*");
    if (error) {
      console.warn("Supabase custom_drugs fetch warning:", error.message);
      return false;
    }

    if (Array.isArray(data) && data.length > 0) {
      const raw = localStorage.getItem(CUSTOM_DRUGS_STORAGE_KEY);
      const store = raw ? JSON.parse(raw) : { deletedIds: [], modified: {}, addedDrugs: [] };
      if (!store.addedDrugs) store.addedDrugs = [];

      let hasChanges = false;
      if (!store.modified) store.modified = {};
      if (!store.addedDrugs) store.addedDrugs = [];

      data.forEach(row => {
        const drug = row.data || row;
        if (!drug || !drug.id) return;
        
        // Luôn lưu vào modified để áp dụng cho cả thuốc trong cơ sở dữ liệu gốc (như Tranexamic, Vitamin 3B)
        store.modified[drug.id] = drug;

        const idx = store.addedDrugs.findIndex(d => d.id === drug.id);
        if (idx >= 0) {
          store.addedDrugs[idx] = drug;
        } else {
          store.addedDrugs.push(drug);
        }
        hasChanges = true;
      });

      if (hasChanges) {
        localStorage.setItem(CUSTOM_DRUGS_STORAGE_KEY, JSON.stringify(store));
        console.log(`Đã đồng bộ thành công ${data.length} thuốc từ Supabase Cloud!`);
        return true;
      }
    }
  } catch (err) {
    console.warn("Lỗi khi đồng bộ Supabase Cloud:", err);
  }
  return false;
}

if (typeof window !== "undefined") {
  window.getActiveDrugsDatabase = getActiveDrugsDatabase;
  window.syncCustomDrugsFromSupabase = syncCustomDrugsFromSupabase;
}
